/* TEAM CODE (owner: Jack - audio input and SD storage) - written by the BJT2 team, not generated by STM32CubeMX. */
/* The bookkeeping of one recording: how many bytes are on the card, and
 * whether to go on or stop safely after each write (see recording_session.h
 * for the rules and what the requirement numbers mean).
 *
 * No task of its own: jack_audio_sd.c calls it inside JackStorageTask.
 *   1. recording_start() when a recording starts;
 *   2. recording_write_chunk() for every full 32 KB staging buffer and for
 *      the last part: Storage_WriteChunk (jack_ports.c: one timed f_write),
 *      then by its result:
 *        OK                 count the bytes, clear the slow counter
 *        SLOW (over 150 ms) count the bytes (they did land), slow counter
 *                           + 1; the third in a row stops it (FAULT)
 *        anything else      (WRITE_FAIL, FULL, ...) stop at once (FAULT);
 *                           last_fault says why
 *   3. recording_stop() at the end; a FAULT stays FAULT so the caller can
 *      still say why the recording stopped.
 * Pure logic, no RTOS or HAL (tests: Tests/test_recording_session.c). */
#include "recording_session.h"

void recording_start(recording_session_t *session)
{
    if (session == NULL)
    {
        return;
    }
    session->state = REC_STATE_RECORDING;
    session->bytes_written = 0U;
    session->consecutive_slow_writes = 0U;
    session->last_fault = STORAGE_OK;
}

storage_result_t recording_write_chunk(recording_session_t *session,
                                        const uint8_t *data,
                                        size_t len)
{
    if ((session == NULL) || (data == NULL) || (len == 0U))
    {
        return STORAGE_INVALID_ARG;
    }

    if (session->state != REC_STATE_RECORDING)
    {
        /* Not currently recording (idle or already faulted) - reject */
        return STORAGE_INVALID_ARG;
    }

    const storage_result_t result = Storage_WriteChunk(data, len);

    switch (result)
    {
        case STORAGE_OK:
            session->bytes_written += (uint32_t)len;
            session->consecutive_slow_writes = 0U;
            break;

        case STORAGE_SLOW:
            /* The write did land, so the data is safely stored, but
             * throughput is degrading (approaching CR1's limit). */
            session->bytes_written += (uint32_t)len;
            session->consecutive_slow_writes++;
            if (session->consecutive_slow_writes >= RECORDING_MAX_CONSECUTIVE_SLOW_WRITES)
            {
                session->state = REC_STATE_FAULT;
                session->last_fault = STORAGE_SLOW;
            }
            break;

        case STORAGE_WRITE_FAIL:
        case STORAGE_FULL:
            /* Stop safely and preserve the last valid stored data (1.9). */
            session->state = REC_STATE_FAULT;
            session->last_fault = result;
            break;

        default:
            /* Any other result is treated conservatively as a fault. */
            session->state = REC_STATE_FAULT;
            session->last_fault = result;
            break;
    }

    return result;
}

void recording_stop(recording_session_t *session)
{
    if (session == NULL)
    {
        return;
    }
    if (session->state == REC_STATE_RECORDING)
    {
        session->state = REC_STATE_IDLE;
    }
    /* If already in FAULT, leave it as FAULT so the caller/UI can still
     * see and report why recording stopped. */
}
